5	/**
6	 * Shared formatting for an owner's customer code: {@code <LAST3>-<NNNN>}, where LAST3 is
7	 * the upper-cased first three letters of the last name and NNNN is a 4-digit zero-padded
8	 * global sequence (e.g. {@code SMI-0007}).
9	 */
10	final class OwnerCustomerCodes {
11	
12	    private OwnerCustomerCodes() {
13	    }
14	
15	    /** Format {@code lastName} and {@code sequence} as {@code <LAST3>-<NNNN>}. */
16	    static String format(String lastName, int sequence) {
17	        return prefix(lastName) + "-" + String.format("%04d", sequence);
18	    }
19	
20	    /** The upper-cased first three letters of {@code lastName}, ignoring any non-letters. */
21	    private static String prefix(String lastName) {
22	        StringBuilder letters = new StringBuilder(3);
23	        for (int i = 0; lastName != null && i < lastName.length() && letters.length() < 3; i++) {
24	            char c = lastName.charAt(i);
25	            if (Character.isLetter(c)) {
26	                letters.append(c);
27	            }
28	        }
29	        return letters.toString().toUpperCase(Locale.ROOT);
30	    }
31	}
